commit 3b5f0a722955878f1d519a9f6f1f42c067f435c4
Author: loop-bench <loop-bench@localhost>
Date:   Fri Nov 6 06:41:48 2026 +0100

    test(orchestrator): fix acceptance test config and expects

    The acceptance test built PromptBuilder from a config shape that no
    longer exists (baseSystemPrompt/systemPromptSuffix/contextConfig), so
    typecheck failed, and asserted with three expect calls where lint
    allows one. It now uses the current PromptBuilderConfig ({identity})
    and one object assertion that pins the rejection message at the
    caller, onError receiving the thrown error instance, and afterSession
    having run. The spec's citation to the test is repointed from #L40 to
    #L33 by scripts/check-spec-anchor-names.mjs --fix.

    Co-Authored-By: Claude Code <noreply@anthropic.com>

diff --git a/src/orchestration/chatOrchestrator.beforeSession.acceptance.test.ts b/src/orchestration/chatOrchestrator.beforeSession.acceptance.test.ts
index 7c4797f..7902487 100644
--- a/src/orchestration/chatOrchestrator.beforeSession.acceptance.test.ts
+++ b/src/orchestration/chatOrchestrator.beforeSession.acceptance.test.ts
@@ -26,42 +26,41 @@ function createMockProvider(response: string): AIProvider {
   };
 }

-const promptBuilder = new PromptBuilder({
-  baseSystemPrompt: 'You are HAL.',
-  systemPromptSuffix: 'Be precise.',
-  contextConfig: {
-    historyLength: 10,
-    includeTimestamps: false,
-    includeSystemPrompt: true,
-  },
-});
+const outcomeOf = (call: Promise<unknown>): Promise<string> =>
+  call.then(() => 'resolved without throwing').catch((error: Error) => error.message);

 describe('beforeSession throwing', () => {
   it('runs onError and afterSession when beforeSession throws', async () => {
     const errorToThrow = new Error('Database connection failed in beforeSession');

-    let caughtError: Error | undefined;
+    let onErrorSawThrown = false;
     let afterSessionRan = false;

-    const orchestrator = createChatOrchestrator(createMockProvider('hello back'), promptBuilder, undefined, {
-      hooks: {
-        beforeSession: async () => {
-          throw errorToThrow;
-        },
-        onError: async (_session, error) => {
-          caughtError = error;
+    const orchestrator = createChatOrchestrator(
+      createMockProvider('hello back'),
+      new PromptBuilder({identity: 'You are HAL.'}),
+      undefined,
+      {
+        hooks: {
+          beforeSession: async () => {
+            throw errorToThrow;
+          },
+          onError: async (_session, error) => {
+            onErrorSawThrown = error === errorToThrow;
+          },
+          afterSession: async () => {
+            afterSessionRan = true;
+          },
         },
-        afterSession: async () => {
-          afterSessionRan = true;
-        },
-      },
-    });
-
-    await expect(orchestrator.processMessage(createSession('hello'))).rejects.toThrow(
-      'Database connection failed in beforeSession'
+      }
     );

-    expect(caughtError).toBe(errorToThrow);

